 const order={critical:0,high:1,medium:2,low:3};STATE.issues.sort((a,b)=>order[a.severity]-order[b.severity]);$('issuesBox').innerHTML=STATE.issues.length?STATE.issues.map(i=>`<article class="issue ${i.severity}"><b>${i.severity==='critical'?'CRÍTICO':i.severity==='high'?'ALTA PRIORIDAD':i.severity==='medium'?'PRIORIDAD MEDIA':'MEJORA'} · ${esc(i.title)}</b><small><strong>Por qué importa:</strong> ${esc(i.why)}</small><small><strong>Cómo corregir:</strong> ${esc(i.how)}</small>${i.example?`<small><strong>Ejemplo:</strong> ${esc(i.example)}</small>`:''}</article>`).join(''):'<div class="good-box">No se detectaron observaciones automáticas relevantes. Aun así corresponde la revisión humana final.</div>';
