function buildReport(){if(!STATE.score)return'';return `PROYECTA-IA — INFORME DE REVISIÓN FINAL PRELIMINAR\n\nArchivo: ${STATE.file?.name||''}\nSHA-256: ${STATE.hash}\nEstudiante: ${$('studentName').value}\nProyecto: ${$('projectTitle').value}\nMención: ${$('mention').options[$('mention').selectedIndex].text}\nPuntaje: ${STATE.score.final.toFixed(1)}/100\nDecisión: ${STATE.score.eligible?'APTO PARA REVISIÓN DOCENTE':'TODAVÍA NO APTO'}\n\nRÚBRICA\n${STATE.rubric.map(r=>`- ${r.name}: ${r.score.toFixed(1)}/${r.max} — ${r.detail}`).join('\n')}\n\nBLOQUEOS CRÍTICOS\n${STATE.locks.length?STATE.locks.map(x=>'- '+x).join('\n'):'Ninguno'}\n\nCORRECCIONES\n${STATE.issues.length?STATE.issues.map((i,n)=>`${n+1}. [${i.severity.toUpperCase()}] ${i.title}\n   Por qué: ${i.why}\n   Cómo: ${i.how}${i.example?`\n   Ejemplo: ${i.example}`:''}`).join('\n\n'):'Sin observaciones automáticas relevantes.'}\n\nNOTA: Este informe es una revisión preliminar automatizada y no sustituye el aval del tutor, la revisión docente ni la evaluación institucional.`}
function downloadText(){const blob=new Blob([buildReport()],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Informe_PROYECTA_IA_revision_final.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

