function deepPrompt(){return `ACTÚA COMO REVISOR FINAL, DOCENTE Y CATEDRÁTICO DE PROYECTOS DE GRADO DE INGENIERÍA ELECTRÓNICA.\n\nDebes revisar el archivo Word completo que adjuntará el estudiante. Usa como marco de evaluación las reglas de PROYECTA-IA y el reglamento institucional. NO inventes información faltante.\n\nDATOS DEL DOCUMENTO ANALIZADO PREVIAMENTE:\n- Estudiante: ${$('studentName').value||'[extraer del Word]'}\n- Título: ${$('projectTitle').value||'[extraer del Word]'}\n- Mención: ${$('mention').options[$('mention').selectedIndex].text}\n- Puntaje automático preliminar: ${STATE.score?.final??'[sin calcular]'} / 100\n- SHA-256: ${STATE.hash||'[sin calcular]'}\n\nREVISA DE FORMA INTEGRAL:\n1. Preliminares: carátula, dedicatoria/agradecimiento opcionales, tabla de contenido, listas, resumen en 4 párrafos y máximo 250 palabras.\n2. Formato: carta; Times New Roman; márgenes 3,5 cm izquierdo y 2,5 cm restantes; interlineado 1,5; párrafos máximo aprox. 10 líneas; paginación; título de tabla de contenido y resumen a 7 cm según reglamento.\n3. Títulos: CAPÍTULO 16 pt negrilla mayúsculas; 1.1 14 pt mayúsculas; 1.1.1 12 pt mayúsculas; desde 1.1.1.1, 12 pt negrilla y tipo oración/minúsculas.\n4. Redacción científica: tercera persona/impersonal; detectar pronombres y verbos en primera persona, particularmente terminaciones -amos, -emos, -imos.\n5. Capítulo I completo: introducción, antecedentes de proyectos (no marco teórico), objeto de estudio, planteamiento cuantitativo con fuentes, formulación, objetivos, justificaciones, alcances, limitaciones y metodología.\n6. Capítulo II: estructura derivada de objetivos, citas APA 6, teoría pertinente, redacción científica y máximo 25 % del total de páginas de los capítulos I-VI.\n7. Capítulo III: arquitectura, sistemas/subsistemas, diseño, selección tecnológica, cálculos/modelos matemáticos, hardware, algoritmos/diagramas de flujo, software/firmware, programación, simulación cuando proceda e implementación. Telecomunicaciones puede concentrarse en diseño de red cuando corresponda.\n8. Capítulo IV: pruebas, resultados, análisis/evaluación técnica; mediciones repetidas (mínimo 3, preferible 10 cuando corresponda), media, desviación/varianza/error/incertidumbre, cifras significativas, SI y referentes externos.\n9. Capítulo V: costos y consolidación; evaluación económica solo cuando corresponda; B/C, VAN, TIR, TRC, ROI u otros únicamente con datos justificables.\n10. Capítulo VI: conclusiones derivadas de los objetivos y evidencias; recomendaciones futuras concretas.\n11. Figuras/tablas: numeración capítulo.consecutivo, título, fuente, nota cuando corresponda, mención desde párrafo superior, explicación posterior; tablas sin líneas horizontales internas según formato adoptado; imágenes suficientemente nítidas para impresión.\n12. APA 6: citas textuales cortas/largas, paráfrasis, p./pp., correspondencia cita↔referencia y fuentes reales/verificables.\n13. Parte final: referencias, glosario, apéndices propios y anexos externos.\n14. Coherencia transversal: problema↔formulación↔objetivo general↔objetivos específicos↔ingeniería↔pruebas↔conclusiones.\n\nPONDERA SOBRE 100 Y USA EL UMBRAL 90. Si es <90, NO autorices el envío al docente: enumera correcciones por prioridad, explica por qué y cómo corregir con ejemplos breves. Si es ≥90, indica “APTO PARA REVISIÓN DOCENTE”, pero aclara que no constituye aprobación final.\n\nNO redactes de nuevo todo el Proyecto de Grado. Actúa como revisor: señala, explica y orienta.\n\nAl final presenta:\nA. NOTA /100\nB. DICTAMEN\nC. FORTALEZAS\nD. CORRECCIONES CRÍTICAS\nE. CORRECCIONES MENORES\nF. COHERENCIA DE CAPÍTULOS I-VI\nG. FORMATO Y REDACCIÓN\nH. APA 6 Y REFERENCIAS\nI. FIGURAS Y TABLAS\nJ. LISTA FINAL DE LO QUE EL DOCENTE DEBE REVISAR MANUALMENTE.`}

async function handleFile(file){if(!file)return;if(!/\.docx$/i.test(file.name)){alert('Este revisor final requiere el archivo Word .DOCX para poder inspeccionar también su formato.');return}STATE={file,buffer:null,hash:'',doc:null,score:null,issues:[],rubric:[],locks:[],sections:{},pageRatio:null};$('progressBar').style.width='15%';$('fileStatus').textContent='Leyendo archivo...';try{const buf=await file.arrayBuffer();STATE.buffer=buf;$('progressBar').style.width='35%';STATE.hash=await sha256(buf);$('progressBar').style.width='50%';STATE.doc=await parseDocx(buf);STATE.sections=buildSections(STATE.doc.text);$('progressBar').style.width='75%';const cover=extractCover(STATE.doc);if(cover.name)$('studentName').value=cover.name;if(cover.title)$('projectTitle').value=cover.title;const pg=findTocPages(STATE.doc.text);for(const [k,v] of Object.entries(pg))if($(k))$(k).value=v;showPageRatio();$('progressBar').style.width='100%';$('fileStatus').textContent='Archivo preparado para revisión.';$('analyzeBtn').disabled=false;const fm=formatAnalysis(STATE.doc);$('fileMeta').innerHTML=`<div class="meta-card"><small>Archivo</small><b>${esc(file.name)}</b></div><div class="meta-card"><small>Páginas (metadato Word)</small><b>${STATE.doc.pages||'No disponible'}</b></div><div class="meta-card"><small>Imágenes incrustadas</small><b>${STATE.doc.media}</b></div><div class="meta-card"><small>SHA-256</small><b class="code-hash">${STATE.hash.slice(0,24)}…</b></div><div class="meta-card"><small>Papel detectado</small><b>${fm.letter?'Carta':'Revisar'}</b></div><div class="meta-card"><small>Márgenes</small><b>Izq ${fm.margins.left.toFixed(2)} · Der ${fm.margins.right.toFixed(2)} · Sup ${fm.margins.top.toFixed(2)} · Inf ${fm.margins.bottom.toFixed(2)} cm</b></div><div class="meta-card"><small>Capítulos detectados</small><b>${['c1','c2','c3','c4','c5','c6'].filter(k=>sectionPresence(STATE.sections[k])).length}/6</b></div><div class="meta-card"><small>Primera persona (preconteo)</small><b>${firstPersonHits(STATE.doc.text).length} coincidencias</b></div>`;$('fileMeta').classList.remove('hidden')}catch(e){console.error(e);$('fileStatus').textContent='No se pudo analizar el DOCX: '+e.message;$('progressBar').style.width='0%';$('analyzeBtn').disabled=true}}

$('docxFile').addEventListener('change',e=>handleFile(e.target.files[0]));$('analyzeBtn').addEventListener('click',()=>{if(STATE.doc){showPageRatio();scoreDocument();document.getElementById('resultado').scrollIntoView({behavior:'smooth'})}});$('pageCalcBtn').addEventListener('click',showPageRatio);$('downloadReportBtn').addEventListener('click',downloadText);$('certificateBtn').addEventListener('click',certificatePDF);$('copyDeepPromptBtn').addEventListener('click',async()=>{await navigator.clipboard.writeText(deepPrompt());$('promptStatus').textContent='Prompt copiado.';setTimeout(()=>$('promptStatus').textContent='',1600)});$('clearBtn').addEventListener('click',()=>location.reload());
